def __exit__(self, exc_type, exc_val, exc_tb):
    try:
        self._stream_mgr.__exit__(exc_type, exc_val, exc_tb)
    finally:
        if exc_type is not None and not self._finalized:
            self._finalized = True
            _err(self._span, exc_val)
        else:
            self._finalize()

async def __aexit__(self, exc_type, exc_val, exc_tb):
    try:
        await self._stream_mgr.__aexit__(exc_type, exc_val, exc_tb)
    finally:
        if exc_type is not None and not self._finalized:
            self._finalized = True
            _err(self._span, exc_val)
        else:
            self._finalize()
